:root {
  --bg: #1e1e2e;
  --card-bg: #2a2a3c;
  --text: #e0e0e0;
  --accent: #f38ba8;
  --accent-hover: #f5a3b8;
  --step-off: #45475a;
  --step-on: #a6e3a1;
  --step-on-hover: #b8f0b3;
  --playhead: #f9e2af;
  --focus: #89b4fa;
  --border-radius: 12px;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
  font-size: 16px;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border-radius: var(--border-radius);
  padding: 24px;
  max-width: 640px;
  width: 100%;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
}

header {
  text-align: center;
  margin-bottom: 24px;
}

h1 {
  font-size: 2rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--accent);
}

.subtitle {
  font-size: 1rem;
  color: #a6adc8;
  margin-top: 4px;
}

.controls {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  align-items: center;
  justify-content: center;
  margin-bottom: 24px;
}

.btn {
  background: var(--step-off);
  color: var(--text);
  border: 2px solid transparent;
  border-radius: 8px;
  padding: 10px 20px;
  font-size: 1rem;
  font-family: var(--font);
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s, transform 0.1s;
  min-width: 80px;
}

.btn:hover {
  background: #585b70;
}

.btn:active {
  transform: scale(0.96);
}

.btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.btn.primary {
  background: var(--accent);
  color: #1e1e2e;
}

.btn.primary:hover {
  background: var(--accent-hover);
}

.bpm-control {
  display: flex;
  align-items: center;
  gap: 8px;
}

.bpm-control label {
  font-weight: 600;
  font-size: 1rem;
}

.bpm-control input {
  width: 72px;
  padding: 8px 10px;
  border-radius: 8px;
  border: 2px solid var(--step-off);
  background: var(--bg);
  color: var(--text);
  font-size: 1rem;
  font-family: var(--font);
  text-align: center;
}

.bpm-control input:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
  border-color: var(--focus);
}

.grid-container {
  display: grid;
  grid-template-columns: repeat(8, 1fr);
  gap: 8px;
  justify-items: center;
}

.step {
  width: 100%;
  max-width: 56px;
  aspect-ratio: 1;
  border-radius: 8px;
  border: 2px solid transparent;
  background: var(--step-off);
  cursor: pointer;
  transition: background 0.1s, border-color 0.1s, transform 0.1s;
  position: relative;
}

.step:hover {
  background: #585b70;
}

.step:active {
  transform: scale(0.92);
}

.step:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.step.on {
  background: var(--step-on);
}

.step.on:hover {
  background: var(--step-on-hover);
}

.step.playhead::after {
  content: '';
  position: absolute;
  inset: -4px;
  border: 3px solid var(--playhead);
  border-radius: 10px;
  pointer-events: none;
}

.step.playhead.on::after {
  border-color: var(--playhead);
}

/* Row labels */
.grid-container {
  grid-template-columns: auto repeat(8, 1fr);
  gap: 6px 8px;
  align-items: center;
}

.row-label {
  font-size: 0.9rem;
  font-weight: 600;
  color: #a6adc8;
  text-align: right;
  padding-right: 4px;
  white-space: nowrap;
}

@media (max-width: 480px) {
  .card {
    padding: 16px;
  }
  h1 {
    font-size: 1.6rem;
  }
  .grid-container {
    gap: 4px 6px;
  }
  .row-label {
    font-size: 0.8rem;
  }
  .step {
    max-width: 40px;
  }
  .btn {
    padding: 8px 14px;
    font-size: 0.9rem;
    min-width: 64px;
  }
  .bpm-control input {
    width: 60px;
  }
}

@media (max-width: 360px) {
  .grid-container {
    grid-template-columns: auto repeat(8, 1fr);
    gap: 3px 4px;
  }
  .row-label {
    font-size: 0.7rem;
  }
  .step {
    max-width: 32px;
  }
}

(function() {
  'use strict';

  const INSTRUMENTS = ['Kick', 'Snare', 'Hi-hat', 'Clap'];
  const STEPS = 8;

  const gridContainer = document.querySelector('.grid-container');
  const playBtn = document.getElementById('playBtn');
  const clearBtn = document.getElementById('clearBtn');
  const bpmInput = document.getElementById('bpmInput');

  let isPlaying = false;
  let currentStep = -1;
  let timerId = null;

  // Build grid
  const steps = [];
  for (let row = 0; row < INSTRUMENTS.length; row++) {
    const label = document.createElement('div');
    label.className = 'row-label';
    label.textContent = INSTRUMENTS[row];
    gridContainer.appendChild(label);

    for (let col = 0; col < STEPS; col++) {
      const btn = document.createElement('button');
      btn.className = 'step';
      btn.dataset.row = row;
      btn.dataset.col = col;
      btn.setAttribute('aria-label', `${INSTRUMENTS[row]} step ${col + 1}`);
      btn.setAttribute('aria-pressed', 'false');
      btn.addEventListener('click', toggleStep);
      gridContainer.appendChild(btn);
      steps.push(btn);
    }
  }

  function toggleStep(e) {
    const btn = e.currentTarget;
    const on = btn.classList.toggle('on');
    btn.setAttribute('aria-pressed', on ? 'true' : 'false');
  }

  function clearGrid() {
    steps.forEach(btn => {
      btn.classList.remove('on');
      btn.setAttribute('aria-pressed', 'false');
    });
  }

  function getBpm() {
    let bpm = parseInt(bpmInput.value, 10);
    if (isNaN(bpm) || bpm < 40) bpm = 40;
    if (bpm > 240) bpm = 240;
    bpmInput.value = bpm;
    return bpm;
  }

  function getStepDuration() {
    // 8 steps per bar, 4 beats per bar (common time)
    return (60 / getBpm()) * 1000 / 2; // eighth notes
  }

  function highlightStep(stepIndex) {
    steps.forEach(btn => btn.classList.remove('playhead'));
    if (stepIndex >= 0) {
      steps.forEach(btn => {
        if (parseInt(btn.dataset.col, 10) === stepIndex) {
          btn.classList.add('playhead');
        }
      });
    }
  }

  function tick() {
    currentStep = (currentStep + 1) % STEPS;
    highlightStep(currentStep);
  }

  function startPlayback() {
    if (isPlaying) return;
    isPlaying = true;
    playBtn.textContent = '⏸ Pause';
    playBtn.setAttribute('aria-label', 'Pause');
    currentStep = -1;
    tick();
    timerId = setInterval(tick, getStepDuration());
  }

  function stopPlayback() {
    isPlaying = false;
    playBtn.textContent = '▶ Play';
    playBtn.setAttribute('aria-label', 'Play');
    clearInterval(timerId);
    timerId = null;
    highlightStep(-1);
  }

  function togglePlayback() {
    if (isPlaying) {
      stopPlayback();
    } else {
      startPlayback();
    }
  }

  playBtn.addEventListener('click', togglePlayback);
  clearBtn.addEventListener('click', clearGrid);

  bpmInput.addEventListener('change', () => {
    getBpm();
    if (isPlaying) {
      clearInterval(timerId);
      timerId = setInterval(tick, getStepDuration());
    }
  });

  // Keyboard: space/enter on steps already works via button
  // Additional: press Escape to stop
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && isPlaying) {
      stopPlayback();
    }
  });
})();
